private TreeNode<T> rotateRight(TreeNode<T> node){
    if(node == null){
        throw new IllegalArgumentException("The node cannot be null");
    }
    TreeNode<T> parent = node.getParent();
    if(parent == null){
        throw new IllegalArgumentException("The node does not have a parent");
    }
    if(parent.getLeft() != node){
        throw new IllegalArgumentException("The node is not the left child of its parent");
    }

    TreeNode<T> child = parent.getLeft();
    if(child == null){
        throw new IllegalArgumentException("The left child of the parent is null");
    }
    // Perform the rotation
    parent.setLeft(child.getRight());
    node.setRight(child);
}

